/* ------------------------------------------------------------------ 3. mp3raw */
const Mp3Raw: React.FC<SceneProps> = ({t}) => {
  const x = 180, w = 1560, lo = 4000, hi = 6000, base = 640;
  const px = (v: number) => x + ((v - lo) / (hi - lo)) * w;
  return (
    <>
      <HeadS over="MP3 · libmp3lame · -write_xing 0" title="No tag, and the sound is late." color={C.red} o={ep(t, 0.2, 0.8)} />
      <Txt x={960} y={285} w={900} size={110} color={C.red} align="center" font="display" o={ep(t, 6.0, 6.8)}>+{fmt(E.mp3.rawShift)}</Txt>
      <Ruler x={x} y={base} w={w} lo={lo} hi={hi} step={500} o={ep(t, 0.8, 1.4)} />
      <Spike x={px(E.mp3.ctlPeak)} y={base} h={130} color={C.cyan} o={ep(t, 1.6, 2.2)} />
      <Txt x={px(E.mp3.ctlPeak)} y={base - 232} w={500} size={46} color={C.cyan} align="center" font="display" o={ep(t, 2.0, 2.6)}>{fmt(E.mp3.ctlPeak)}</Txt>
      <Txt x={px(E.mp3.ctlPeak)} y={base - 168} w={500} size={22} color={C.dim} align="center" font="mono" o={ep(t, 2.0, 2.6)}>control: through PCM</Txt>
      <Spike x={px(E.mp3.rawPeak)} y={base} h={130} color={C.red} o={ep(t, 4.0, 4.6)} />
      <Txt x={px(E.mp3.rawPeak)} y={base - 232} w={500} size={46} color={C.red} align="center" font="display" o={ep(t, 4.4, 5.0)}>{fmt(E.mp3.rawPeak)}</Txt>
      <Txt x={px(E.mp3.rawPeak)} y={base - 168} w={500} size={22} color={C.dim} align="center" font="mono" o={ep(t, 4.4, 5.0)}>no tag: decoded raw</Txt>
      <Brace x1={px(E.mp3.ctlPeak)} x2={px(E.mp3.rawPeak)} y={base + 78} label={`${fmt(E.mp3.rawShift)} samples late`} o={ep(t, 5.4, 6.0)} />
      <Txt x={960} y={base + 150} w={1500} size={30} color={C.dim} align="center" font="mono" o={ep(t, 8.0, 8.8)}>{fmt(E.mp3.inSamples)} samples in · {fmt(E.mp3.rawSamples)} samples out</Txt>
    </>
  );
};

/* ------------------------------------------------------------------ 4. mp3tag */
const Mp3Tag: React.FC<SceneProps> = ({t}) => {
  const [b0, b1, b2] = [E.mp3.delayHex.slice(0, 2), E.mp3.delayHex.slice(2, 4), E.mp3.delayHex.slice(4, 6)];
  const delay12 = parseInt(E.mp3.delayHex.slice(0, 3), 16), pad12 = parseInt(E.mp3.delayHex.slice(3, 6), 16);
  const x = 180, w = 1560, total = E.mp3.noSkip;
  const sx = (n: number) => (n / total) * w;
  const segs = [
    {n: E.mp3.delay, color: C.amber, key: 'delay'},
    {n: E.mp3.decExtra, color: C.violet, key: 'dec'},
    {n: E.mp3.tagSamples, color: C.green, key: 'audio'},
    {n: E.mp3.trim, color: C.red, key: 'trim'},
  ];
  let acc = 0;
  const sxs = segs.map((sg) => { const l = x + sx(acc); acc += sg.n; return l; });
  const fileMax = E.mp3.delayAt + 40;
  const fx = (b: number) => x + (b / fileMax) * w;
  const hexCell = (xx: number, label: string, col: string, o: number) => (
    <Box x={xx} y={430} w={100} h={74} color={col} o={o}><Txt box x={0} y={14} w={94} size={42} align="center" font="mono" weight={700}>{label}</Txt></Box>
  );
  return (
    <>
      <HeadS over="MP3 · the default Info tag" title="Tagged: back where it was." color={C.green} o={ep(t, 0.2, 0.8)} />
      {/* file offsets */}
      <div style={{position: 'absolute', left: x, top: 330, width: w, height: 4, background: C.mute, opacity: ep(t, 0.8, 1.4)}} />
      {[[E.mp3.tagAt, 'Info', C.cyan], [E.mp3.lameAt, 'encoder', C.dim], [E.mp3.delayAt, `${b0} ${b1} ${b2}`, C.amber]].map(([b, lab, col], i) => (
        <React.Fragment key={i}>
          <div style={{position: 'absolute', left: fx(b as number) - 2, top: 318, width: 4, height: 28, background: col as string, opacity: ep(t, 1.2 + i * 0.6, 1.8 + i * 0.6)}} />
          <Txt x={fx(b as number)} y={282} w={400} size={24} color={col as string} align="center" font="mono" weight={700} o={ep(t, 1.2 + i * 0.6, 1.8 + i * 0.6)}>{lab as string}</Txt>
          <Txt x={fx(b as number)} y={352} w={300} size={19} color={C.dim} align="center" font="mono" o={ep(t, 1.2 + i * 0.6, 1.8 + i * 0.6)}>byte {b as number}</Txt>
        </React.Fragment>
      ))}
      {/* the three bytes, split in two 12 bit numbers */}
      {hexCell(560, b0, C.amber, ep(t, 3.4, 4.0))}
      {hexCell(670, b1, C.amber, ep(t, 3.6, 4.2))}
      {hexCell(780, b2, C.amber, ep(t, 3.8, 4.4))}
      <Txt x={920} y={438} w={90} size={44} color={C.mute} align="center" font="display" o={ep(t, 4.4, 4.9)}>→</Txt>
      <Txt x={1010} y={426} w={380} size={44} color={C.amber} font="display" o={ep(t, 4.6, 5.2)}>delay {fmt(delay12)}</Txt>
      <Txt x={1010} y={496} w={420} size={44} color={C.red} font="display" o={ep(t, 5.0, 5.6)}>padding {fmt(pad12)}</Txt>
      {/* where they go */}
      {segs.map((sg, i) => (
        <Box key={sg.key} x={sxs[i]} y={650} w={Math.max(4, sx(sg.n))} h={70} color={sg.color} fill={`${sg.color}66`} r={3} bw={2} o={ep(t, 6.2 + i * 0.5, 6.8 + i * 0.5)} />
      ))}
      <Txt x={sxs[0]} y={590} w={500} size={26} color={C.amber} font="mono" weight={700} o={ep(t, 6.4, 7.0)}>{fmt(E.mp3.delay)} delay</Txt>
      <Txt x={sxs[1] + 20} y={548} w={640} size={26} color={C.violet} font="mono" weight={700} o={ep(t, 6.9, 7.5)}>+ {fmt(E.mp3.decExtra)} decoder = {fmt(E.mp3.skip)} skipped</Txt>
      <Txt x={sxs[3] + sx(E.mp3.trim)} y={590} w={400} size={26} color={C.red} font="mono" weight={700} align="right" o={ep(t, 7.9, 8.5)}>{fmt(E.mp3.trim)} trimmed</Txt>
      <Txt x={x + sx(E.mp3.skip) + sx(E.mp3.tagSamples) / 2} y={734} w={900} size={34} color={C.green} align="center" font="mono" weight={700} o={ep(t, 7.4, 8.0)}>{fmt(E.mp3.tagSamples)} samples left · impulse at {fmt(E.mp3.tagPeak)}</Txt>
      <Txt x={x} y={800} w={1500} size={22} color={C.dim} font="mono" o={ep(t, 8.6, 9.2)}>bar drawn to scale: {fmt(E.mp3.noSkip)} samples out of the decoder before trimming</Txt>
    </>
  );
};

/* ------------------------------------------------------------------ 5. opushead */
const OpusHead: React.FC<SceneProps> = ({t}) => {
  const bytes = E.opus.hex.match(/../g) as string[];
  const asc = (h: string) => String.fromCharCode(parseInt(h, 16));
  const cw = 76, gap = 6, x0 = Math.round((1920 - (bytes.length * (cw + gap) - gap)) / 2), y = 350;
  const le = parseInt(E.opus.preHex.slice(2, 4) + E.opus.preHex.slice(0, 2), 16);
  const fields: [number, number, string][] = [[0, 8, 'magic'], [8, 9, 'ver'], [9, 10, 'ch'], [10, 12, 'pre-skip'], [12, 16, 'rate'], [16, 18, 'gain'], [18, 19, 'map']];
  const hot = (i: number) => i === 10 || i === 11;
  return (
    <>
      <HeadS over="Opus · the OpusHead packet" title={`Pre-skip: ${E.opus.pre} samples.`} o={ep(t, 0.2, 0.8)} />
      {fields.map(([a, b, lab]) => {
        const l = x0 + a * (cw + gap), w = (b - a) * (cw + gap) - gap;
        const isHot = lab === 'pre-skip';
        return (
          <React.Fragment key={lab}>
            <div style={{position: 'absolute', left: l, top: y - 40, width: w, height: 3, background: isHot ? C.amber : C.mute, opacity: ep(t, 0.9, 1.5)}} />
            <Txt x={l + w / 2} y={y - 36 - 26} w={w + 20} size={20} color={isHot ? C.amber : C.dim} align="center" font="mono" weight={700} o={ep(t, 0.9, 1.5)}>{lab}</Txt>
          </React.Fragment>
        );
      })}
      {bytes.map((h, i) => (
        <Box key={i} x={x0 + i * (cw + gap)} y={y} w={cw} h={84} color={hot(i) ? C.amber : C.mute} fill={hot(i) ? `${C.amber}44` : `${C.mute}1a`} bw={hot(i) ? 4 : 2} o={ep(t, 1.0 + i * 0.05, 1.4 + i * 0.05)}>
          <Txt box x={0} y={10} w={cw - 6} size={36} color={hot(i) ? C.text : C.dim} align="center" font="mono" weight={700}>{h}</Txt>
          {i < 8 && <Txt box x={0} y={52} w={cw - 6} size={22} color={C.mute} align="center" font="mono">{asc(h)}</Txt>}
        </Box>
      ))}
      <Txt x={x0 + 10.5 * (cw + gap)} y={y + 100} w={700} size={34} color={C.amber} align="center" font="mono" weight={700} o={ep(t, 3.6, 4.2)}>{E.opus.preHex.slice(0, 2)} {E.opus.preHex.slice(2, 4)} little endian = {fmt(le)}</Txt>
      <Txt x={x0 + 10.5 * (cw + gap)} y={y + 146} w={700} size={26} color={C.dim} align="center" font="mono" o={ep(t, 4.2, 4.8)}>{fmt(le)} / 48 = {E.opus.preMs} ms</Txt>
      {E.opus.boxes.map((b: any, i: number) => {
        const name = ({ogg: 'ogg', oggp: 'ogg · 100 ms pages', mkv: 'mkv', opus: '.opus'} as Record<string, string>)[b.k];
        const l = 120 + i * 430;
        return (
          <Card key={b.k} x={l} y={640} w={400} h={170} color={C.green} o={ep(t, 5.4 + i * 0.5, 6.0 + i * 0.5)}>
            <Txt x={24} y={18} w={350} size={22} color={C.green} weight={700} caps>{name}</Txt>
            <Txt x={24} y={52} w={350} size={24} color={C.dim} font="mono">pre-skip {b.pre}</Txt>
            <Txt x={24} y={86} w={350} size={46} color={C.text} font="display">click {fmt(b.click)}</Txt>
          </Card>
        );
      })}
    </>
  );
};

