/* ------------------------------------------------------------------ 9. aacjoin */
const AacJoin: React.FC<SceneProps> = ({t}) => {
  const x = 150, w = 1620;
  const unit = E.aac.priming + E.valid + E.aac.padding;
  const total = 2 * unit;
  const s = w / total;
  const segs: [string, number, string][] = [['prim', E.aac.priming, C.red], ['audio', E.valid, C.cyan], ['pad', E.aac.padding, C.amber]];
  const row: React.ReactNode[] = [];
  let acc = 0;
  for (let f = 0; f < 2; f++) for (const [k, n, col] of segs) {
    row.push(<Box key={`${f}${k}`} x={x + acc * s} y={330} w={Math.max(3, n * s)} h={70} color={col} fill={`${col}55`} r={2} bw={2} />);
    acc += n;
  }
  const seam = x + unit * s;
  const zs = 0.55, zw = (E.aac.padding + E.aac.priming) * zs, zx = 960 - zw / 2, zy = 490;
  return (
    <>
      <HeadS over="ffmpeg -f concat · -c copy" title={`${E.copy.packets} packets, one new note.`} color={C.amber} o={ep(t, 0.2, 0.8)} />
      <div style={{position: 'absolute', left: 0, top: 0, opacity: ep(t, 1.0, 1.8)}}>{row}</div>
      <Txt x={x + unit * s * 0.5} y={352} w={600} size={26} color={C.text} align="center" font="mono" weight={700} o={ep(t, 1.2, 1.8)}>a.m4a</Txt>
      <Txt x={x + unit * s * 1.5} y={352} w={600} size={26} color={C.text} align="center" font="mono" weight={700} o={ep(t, 1.2, 1.8)}>b.m4a</Txt>
      <Brace x1={x} x2={x + w} y={312} label={`edit list ${fmt(E.copy.editMs)} ms from media time ${E.copy.media}`} color={C.amber} o={ep(t, 2.4, 3.2)} size={26} above />
      <svg width={1920} height={1080} style={{position: 'absolute', left: 0, top: 0, opacity: ep(t, 4.0, 4.8)}}>
        <line x1={seam} y1={402} x2={zx} y2={zy} stroke={C.mute} strokeWidth={2} strokeDasharray="6 6" />
        <line x1={seam + 3} y1={402} x2={zx + zw} y2={zy} stroke={C.mute} strokeWidth={2} strokeDasharray="6 6" />
      </svg>
      <Box x={zx} y={zy} w={E.aac.padding * zs} h={124} color={C.amber} fill={`${C.amber}55`} r={4} o={ep(t, 4.4, 5.0)}>
        <Txt box x={0} y={20} w={E.aac.padding * zs - 6} size={40} align="center" font="display">{fmt(E.aac.padding)}</Txt>
        <Txt box x={0} y={86} w={E.aac.padding * zs - 6} size={20} align="center" font="mono" weight={700}>padding</Txt>
      </Box>
      <Box x={zx + E.aac.padding * zs} y={zy} w={E.aac.priming * zs} h={124} color={C.red} fill={`${C.red}55`} r={4} o={ep(t, 5.0, 5.6)}>
        <Txt box x={0} y={20} w={E.aac.priming * zs - 6} size={40} align="center" font="display">{fmt(E.aac.priming)}</Txt>
        <Txt box x={0} y={86} w={E.aac.priming * zs - 6} size={20} align="center" font="mono" weight={700}>priming</Txt>
      </Box>
      <Txt x={960} y={640} w={1500} size={36} color={C.text} align="center" font="mono" weight={700} o={ep(t, 6.6, 7.4)}>{fmt(E.aac.joinDecoded)} decoded − {fmt(E.aac.asked)} asked</Txt>
      <Txt x={960} y={686} w={1500} size={80} color={C.red} align="center" font="display" o={ep(t, 7.6, 8.4)}>+{fmt(E.aac.extra)}</Txt>
      <Txt x={960} y={830} w={1500} size={30} color={C.dim} align="center" font="mono" o={ep(t, 8.8, 9.6)}>2 × ({fmt(E.aac.priming)} + {fmt(E.aac.padding)})</Txt>
    </>
  );
};

