/* ------------------------------------------------------------------ 12. cutopus */
const CutOpus: React.FC<SceneProps> = ({t}) => {
  const x = 180, w = 1560, lo = 22500, hi = 25500, pk = E.opus.packet, want = E.opus.cuts.wanted;
  const px = (v: number) => x + ((v - lo) / (hi - lo)) * w;
  const grid: number[] = [];
  for (let v = Math.ceil(lo / pk) * pk; v <= hi; v += pk) grid.push(v);
  const rows = [
    {name: 'mkv · -ss before -i', v: E.opus.cuts.mkvBefore, at: 2.4},
    {name: 'mkv · -ss after -i', v: E.opus.cuts.mkvAfter, at: 4.4},
    {name: 'ogg · -ss after -i', v: E.opus.cuts.oggAfter, at: 6.0},
    {name: 're-encode', v: E.opus.cuts.re, at: 8.0},
  ];
  return (
    <>
      <HeadS over="Opus · -ss 0.5 -c copy" title={`They land on ${pk}-sample packets.`} o={ep(t, 0.2, 0.8)} />
      {grid.map((v) => <div key={v} style={{position: 'absolute', left: px(v) - 1, top: 300, width: 2, height: 490, background: C.line, opacity: ep(t, 0.8, 1.6)}} />)}
      {grid.map((v, i) => i < grid.length - 1 && <Txt key={`g${v}`} x={(px(v) + px(v + pk)) / 2} y={300} w={400} size={20} color={C.mute} align="center" font="mono" o={ep(t, 1.0, 1.6)}>{pk} samples · {E.opus.packetMs} ms</Txt>)}
      <RefLine x={px(want)} y1={330} y2={790} color={C.cyan} o={ep(t, 1.4, 2.0)} />
      {rows.map((r, i) => {
        const y = 345 + i * 105, off = r.v - want, col = off === 0 ? C.green : C.red, o = ep(t, r.at, r.at + 0.6);
        const right = px(r.v) > 1300;
        return (
          <React.Fragment key={r.name}>
            <Spike x={px(r.v)} y={y + 70} h={72} color={col} o={o} thick={5} />
            <Txt x={px(r.v) + (right ? -24 : 24)} y={y - 6} w={640} size={24} color={col} font="mono" weight={700} align={right ? 'right' : 'left'} o={o}>{r.name}</Txt>
            <Txt x={px(r.v) + (right ? -24 : 24)} y={y + 22} w={640} size={40} color={col} font="display" align={right ? 'right' : 'left'} o={o}>{fmt(r.v)} · {off === 0 ? 'exact' : `${fmt(Math.abs(off))} ${off < 0 ? 'early' : 'late'}`}</Txt>
          </React.Fragment>
        );
      })}
      <Ruler x={x} y={790} w={w} lo={lo} hi={hi} step={500} o={ep(t, 0.8, 1.4)} />
    </>
  );
};

/* ------------------------------------------------------------------ 13. which */
const Which: React.FC<SceneProps> = ({t}) => {
  const rows = [
    {goal: 'Join AAC files', doIt: 'trim each input, concat, encode once', never: `-c copy join: ${fmt(E.copy.seam)} at the seam`, at: 1.0},
    {goal: 'Cut at an exact sample', doIt: 're-encode (MP3, Opus)', never: `-c copy cut: ${fmt(E.mp3.cutLate)} late`, at: 4.6},
    {goal: 'Gapless playback', doIt: 'keep the tag', never: `-write_xing 0: ${fmt(E.mp3.rawShift)} late`, at: 7.6},
  ];
  return (
    <>
      <HeadS over="Which command" title="Trim, join, encode once." color={C.green} o={ep(t, 0.2, 0.8)} />
      {rows.map((r, i) => {
        const y = 300 + i * 190, o = ep(t, r.at, r.at + 0.6);
        return (
          <Card key={r.goal} x={120} y={y} w={1680} h={160} color={C.line} o={o}>
            <Txt x={30} y={22} w={460} size={22} color={C.cyan} weight={700} caps>Goal</Txt>
            <Txt x={30} y={62} w={470} size={30} color={C.text} font="display">{r.goal}</Txt>
            <Box x={530} y={26} w={640} h={108} color={C.green} fill={`${C.green}22`}>
              <Txt x={20} y={12} w={560} size={20} color={C.green} weight={700} caps>Do</Txt>
              <Txt x={20} y={50} w={610} size={27} font="mono" weight={700}>{r.doIt}</Txt>
            </Box>
            <Box x={1200} y={26} w={450} h={108} color={C.red} fill={`${C.red}18`} dashed>
              <Txt x={20} y={12} w={400} size={20} color={C.red} weight={700} caps>Never</Txt>
              <Txt x={20} y={52} w={425} size={21} font="mono" weight={700}>{r.never}</Txt>
            </Box>
          </Card>
        );
      })}
    </>
  );
};

/* ------------------------------------------------------------------ 14. recipe */
const Recipe: React.FC<SceneProps> = ({t}) => {
  const lines = (E.rec.cmd as string).replace(' -filter_complex', ' \\\n  -filter_complex').replace(' -c:a', ' \\\n  -c:a').split('\n');
  const c = E.clickEarly;
  const chip = (x: number, w: number, label: string, value: string, col: string, at: number) => (
    <Card x={x} y={780} w={w} h={96} color={col} o={ep(t, at, at + 0.6)}>
      <Txt x={20} y={10} w={w - 30} size={18} color={col} weight={700} caps>{label}</Txt>
      <Txt x={20} y={40} w={w - 30} size={24} font="mono" weight={700}>{value}</Txt>
    </Card>
  );
  return (
    <>
      <HeadS over="The recipe, on a fresh pair" title="Seam 200, like the control." color={C.green} o={ep(t, 0.2, 0.8)} />
      <div style={{position: 'absolute', left: 120, top: 280, width: 1680, height: 140, boxSizing: 'border-box', borderRadius: 14, border: `3px solid ${C.green}`, background: C.codeBg, opacity: ep(t, 0.8, 1.6), padding: '14px 24px', fontFamily: F.mono, fontSize: 24, lineHeight: '1.45', color: C.text, whiteSpace: 'pre'}}>
        {lines.map((l, i) => <div key={i}><span style={{color: i === 0 ? C.green : 'inherit'}}>{i === 0 ? '$ ' : '  '}</span>{l.replace(/atrim=duration=\d+/g, (m) => '\u0000' + m).split('\u0000').map((p, k) => (k === 0 ? <span key={k}>{p}</span> : <span key={k}><span style={{color: C.amber, fontWeight: 700}}>{p.match(/^atrim=duration=\d+/)![0]}</span>{p.replace(/^atrim=duration=\d+/, '')}</span>))}</div>)}
      </div>
      <SeamRow x0={150} y={435} s={0.6} title="PCM control" parts={[{n: c, color: C.cyan, label: `${c}`}, {n: c, color: C.cyan, label: `${c}`}]} value={E.ctl.seam} valueColor={C.cyan} p={ep(t, 3.0, 3.8)} o={ep(t, 3.0, 3.6)} />
      <SeamRow x0={150} y={595} s={0.6} title="Recipe" sub={`clicks ${E.rec.clicks.map(fmt).join(' · ')}`} titleColor={C.green} parts={[{n: c, color: C.green, label: `${c}`}, {n: c, color: C.green, label: `${c}`}]} value={E.rec.seam} valueColor={C.green} p={ep(t, 5.0, 5.8)} o={ep(t, 5.0, 5.6)} />
      {chip(120, 680, 'Reader 1 · decoder', `clicks at ${E.rec.clicks.map(fmt).join(', ')}`, C.green, 6.8)}
      {chip(830, 520, 'Reader 2 · mp4 bytes', `edit list ${fmt(E.rec.editMs)} ms · ${E.rec.packets} packets`, C.green, 8.0)}
      {chip(1380, 420, 'Reader 3 · ffprobe', `duration ${E.rec.probeS} s · ${E.rec.probePackets} packets`, C.green, 9.2)}
    </>
  );
};

/* ------------------------------------------------------------------ 15. cheat */
const Cheat: React.FC<SceneProps> = ({t}) => {
  const rows = [
    {codec: 'MP3', where: 'Info tag', how: `byte ${E.mp3.delayAt}: delay + padding`, val: `delay ${E.mp3.delay} · padding ${fmt(E.mp3.padding)}`, color: C.cyan, at: 1.0},
    {codec: 'Opus', where: 'OpusHead', how: 'the pre-skip field', val: `${E.opus.pre} samples · ${E.opus.preMs} ms`, color: C.green, at: 3.0},
    {codec: 'AAC in mp4', where: 'edit list', how: 'media time of the first edit', val: `${fmt(E.aac.editMs)} ms from ${fmt(E.aac.media)}`, color: C.violet, at: 5.0},
  ];
  return (
    <>
      <HeadS over="Cheat sheet" title="Where each codec keeps the note." o={ep(t, 0.2, 0.8)} />
      <Txt x={150} y={290} w={300} size={18} color={C.mute} weight={700} caps o={ep(t, 0.6, 1.2)}>Codec</Txt>
      <Txt x={520} y={290} w={300} size={18} color={C.mute} weight={700} caps o={ep(t, 0.6, 1.2)}>The note</Txt>
      <Txt x={900} y={290} w={400} size={18} color={C.mute} weight={700} caps o={ep(t, 0.6, 1.2)}>Read it</Txt>
      <Txt x={1380} y={290} w={400} size={18} color={C.mute} weight={700} caps o={ep(t, 0.6, 1.2)}>Our file</Txt>
      {rows.map((r, i) => {
        const y = 330 + i * 125, o = ep(t, r.at, r.at + 0.6);
        return (
          <Card key={r.codec} x={120} y={y} w={1680} h={104} color={r.color} o={o}>
            <Txt x={30} y={20} w={340} size={40} color={r.color} font="display">{r.codec}</Txt>
            <Txt x={400} y={34} w={340} size={32} font="mono" weight={700}>{r.where}</Txt>
            <Txt x={780} y={36} w={480} size={24} color={C.dim} font="mono">{r.how}</Txt>
            <Txt x={1260} y={34} w={400} size={26} color={C.text} font="mono" weight={700}>{r.val}</Txt>
          </Card>
        );
      })}
      <Box x={120} y={720} w={820} h={110} color={C.amber} dashed o={ep(t, 7.0, 7.6)}>
        <Txt x={22} y={12} w={770} size={18} color={C.amber} weight={700} caps>After any copy</Txt>
        <Txt x={22} y={44} w={780} size={24} font="mono" weight={700}>count the decoded samples, find a known click</Txt>
      </Box>
      <Box x={980} y={720} w={820} h={110} color={C.cyan} dashed o={ep(t, 8.4, 9.0)}>
        <Txt x={22} y={12} w={770} size={18} color={C.cyan} weight={700} caps>Run a control first</Txt>
        <Txt x={22} y={44} w={780} size={24} font="mono" weight={700}>through PCM: {fmt(E.mp3.ctlPeak)} · {fmt(E.opus.click)} · {E.ctl.seam}</Txt>
      </Box>
    </>
  );
};

/* ------------------------------------------------------------------ 16. close */
const Close: React.FC<SceneProps> = ({t}) => {
  const items = ['other ffmpeg builds', 'real players', 'other encoders', 'real music', 'stereo', 'other sample rates', 'copy joins of MP3 and Opus', 'sound quality of a second AAC encode'];
  const widths = items.map((it) => Math.round(it.length * 15.6 + 52));
  const place: {x: number; y: number}[] = [];
  let cx = 120, cy = 330;
  widths.forEach((wv) => { if (cx + wv > 1800) { cx = 120; cy += 106; } place.push({x: cx, y: cy}); cx += wv + 24; });
  return (
    <>
      <HeadS over="Not tested" title={`Measured on ffmpeg ${E.ver}, synthetic clicks.`} color={C.amber} o={ep(t, 0.2, 0.9)} />
      {items.map((it, i) => (
        <Box key={it} x={place[i].x} y={place[i].y} w={widths[i]} h={76} color={C.amber} dashed fill="transparent" o={ep(t, 1.2 + i * 0.4, 1.8 + i * 0.4)}>
          <Txt box x={0} y={22} w={widths[i] - 6} size={26} color={C.text} align="center" font="mono" weight={700}>{it}</Txt>
        </Box>
      ))}
      <Txt x={960} y={640} w={1500} size={32} color={C.dim} align="center" font="mono" o={ep(t, 5.4, 6.0)}>The decoder, the file bytes and ffprobe, each against a control.</Txt>
      <Txt x={960} y={730} w={1500} size={30} color={C.dim} align="center" font="mono" o={ep(t, 6.2, 6.8)}>FFmpeg Reality Checks · Deep dive 02 · fixture and tests in the description</Txt>
    </>
  );
};

